  detalii_intretinere?: Prisma.detalii_intretinereOmit
  facturi_furnizori?: Prisma.facturi_furnizoriOmit
  fise_intretinere?: Prisma.fise_intretinereOmit
  fonduri?: Prisma.fonduriOmit
